/*
 * Web-lane probes (review 0.6.32-full, lane L3). Runs the REAL web/app.js,
 * web/webstore.js and web/horizon.js against a fake IndexedDB + a minimal DOM
 * stub in Node - the same technique the project's own tests/js/*.mjs engines use.
 *
 * app-probe.mjs is generated by build_probe_app.py from web/app.js with only the
 * import specifiers retargeted and test hooks appended; every function body is
 * the shipped one.
 */
import { writeFileSync } from 'node:fs';

/* ------------------------------- globals ------------------------------- */
const LS = new Map();
globalThis.localStorage = {
  getItem: (k) => (LS.has(k) ? LS.get(k) : null),
  setItem: (k, v) => { LS.set(k, String(v)); },
  removeItem: (k) => { LS.delete(k); },
};

const _dbs = new Map();                       // dbName -> Map(storeName -> Map)
const storesOf = (n) => { if (!_dbs.has(n)) _dbs.set(n, new Map()); return _dbs.get(n); };
const storeOf = (n, s) => { const d = storesOf(n); if (!d.has(s)) d.set(s, new Map()); return d.get(s); };
const req = () => ({ onsuccess: null, onerror: null, result: null, error: null });
const micro = (fn) => queueMicrotask(fn);

/* fail injection: mode 'ok' | 'throw-open' | 'error-open', and per-store put/clear failures */
const CTL = { open: 'ok', failPut: {}, failClear: {} };

globalThis.indexedDB = {
  open(name) {
    const rq = req();
    if (CTL.open === 'throw-open') {
      const e = new Error('SecurityError: access to IndexedDB is denied');
      e.name = 'SecurityError';
      throw e;
    }
    micro(() => {
      if (CTL.open === 'error-open') {
        rq.error = new Error('SecurityError: access to IndexedDB is denied');
        rq.error.name = 'SecurityError';
        rq.onerror && rq.onerror();
        return;
      }
      const db = {
        objectStoreNames: { contains: (n) => storesOf(name).has(n) },
        createObjectStore: (n) => { storeOf(name, n); return {}; },
        transaction: (sname) => ({
          objectStore: () => ({
            get(key) {
              const r = req();
              micro(() => { const s = storeOf(name, sname); r.result = s.has(key) ? s.get(key) : null; r.onsuccess && r.onsuccess(); });
              return r;
            },
            put(val, key) {
              const r = req();
              micro(() => {
                const c = CTL.failPut[sname];
                if (c && c > 0) { CTL.failPut[sname] = c - 1; r.onerror && r.onerror(); return; }
                storeOf(name, sname).set(key, val);
                r.result = key; r.onsuccess && r.onsuccess();
              });
              return r;
            },
            delete(key) {
              const r = req();
              micro(() => { storeOf(name, sname).delete(key); r.onsuccess && r.onsuccess(); });
              return r;
            },
            clear() {
              const r = req();
              micro(() => {
                const c = CTL.failClear[sname];
                if (c && c > 0) { CTL.failClear[sname] = c - 1; r.onerror && r.onerror(); return; }
                storeOf(name, sname).clear(); r.onsuccess && r.onsuccess();
              });
              return r;
            },
            openCursor() {
              const r = req();
              micro(() => {
                const entries = [...storeOf(name, sname).entries()];
                let i = 0;
                const step = () => {
                  if (i < entries.length) { const [key, value] = entries[i++]; r.result = { key, value, continue: step }; r.onsuccess && r.onsuccess(); }
                  else { r.result = null; r.onsuccess && r.onsuccess(); }
                };
                step();
              });
              return r;
            },
          }),
        }),
      };
      rq.result = db;
      rq.onupgradeneeded && rq.onupgradeneeded();
      rq.onsuccess && rq.onsuccess();
    });
    return rq;
  },
};

/* Fetch stub: per-probe scenario. */
let fetchMode = 'reject';   // 'reject' | '429' | '404' | 'ok' | 'disambig-then-image'
let fetchCalls = [];
globalThis.URL.createObjectURL = globalThis.URL.createObjectURL || (() => 'blob:probe');
globalThis.URL.revokeObjectURL = globalThis.URL.revokeObjectURL || (() => {});
globalThis.fetch = async (url) => {
  fetchCalls.push(String(url));
  const u = String(url);
  if (fetchMode === 'reject') throw new TypeError('Failed to fetch');
  if (fetchMode === '429') return { ok: false, status: 429, json: async () => ({}) };
  if (fetchMode === '404') return { ok: false, status: 404, json: async () => ({}) };
  if (fetchMode === 'disambig-then-image') {
    if (u.includes('Messier%20101')) return { ok: true, status: 200, json: async () => ({ type: 'disambiguation', title: 'M101' }) };
    if (u.includes('NGC%205457')) return { ok: true, status: 200, json: async () => ({ title: 'Pinwheel Galaxy', thumbnail: { source: 'https://upload.wikimedia.org/thumb.jpg' } }) };
    if (u.includes('upload.wikimedia.org')) return { ok: true, status: 200, blob: async () => new Blob(['JPEG'], { type: 'image/jpeg' }) };
    return { ok: false, status: 404, json: async () => ({}) };
  }
  if (u.startsWith('catalog.json')) return { ok: true, status: 200, json: async () => [] };
  return { ok: true, status: 200, json: async () => ({ type: 'disambiguation', title: 'X' }) };
};

/* Minimal DOM. window exists before the import (horizon.js guards on it). */
const winListeners = [];
globalThis.window = {
  matchMedia: () => ({ matches: false }),
  devicePixelRatio: 1,
  addEventListener: (t, fn) => winListeners.push([t, fn]),
  removeEventListener: () => {},
  dispatchEvent: () => {},
  location: { hash: '', href: 'http://localhost/' },
};

const mkStyle = () => ({ cssText: '', display: '', setProperty() {}, removeProperty() {} });
function makeEl(tag) {
  return {
    tagName: String(tag || 'div').toUpperCase(), style: mkStyle(), dataset: {}, hidden: false,
    innerHTML: '', textContent: '', value: '', checked: false, disabled: false, href: '', src: '',
    classList: { add() {}, remove() {}, toggle() {}, contains: () => false },
    addEventListener() {}, removeEventListener() {}, appendChild() {}, remove() {}, click() {},
    querySelector: () => null, querySelectorAll: () => [], focus() {}, blur() {},
    setAttribute() {}, getAttribute: () => null, closest: () => null, contains: () => false,
    getClientRects: () => [], getBoundingClientRect: () => ({ left: 0, top: 0, width: 200, height: 100 }),
    setSelectionRange() {}, isConnected: true, removeAttribute() {},
  };
}
const elCache = new Map();
const q = (sel) => { if (!elCache.has(sel)) elCache.set(sel, makeEl(sel)); return elCache.get(sel); };
const docListeners = [];
globalThis.document = {
  documentElement: makeEl('html'), body: makeEl('body'), hidden: false, activeElement: null,
  createElement: (t) => makeEl(t),
  querySelector: q, querySelectorAll: () => [],
  addEventListener: (t, fn) => docListeners.push([t, fn]), removeEventListener: () => {},
};

/* ------------------------------- harness ------------------------------- */
let pass = 0, fail = 0;
const ok = (c, m) => { if (c) { pass++; console.log('  PASS  ' + m); } else { fail++; console.log('  FAIL  ' + m); } };
const info = (m) => console.log('  ..    ' + m);
const blank720 = () => new Array(720).fill(-90);

const WS = await import(new URL('../../../../web/webstore.js?v=26', import.meta.url).href);
const H = await import(new URL('../../../../web/horizon.js?v=48', import.meta.url).href);
/* document exists now, so app.js's trailing `if (typeof document !== 'undefined') boot()`
   WOULD auto-run - import it while document is temporarily hidden */
const savedDoc = globalThis.document;
delete globalThis.document;
const A = await import(new URL('./app-probe.mjs', import.meta.url).href);
globalThis.document = savedDoc;

console.log('== L3 web lane probes ==========================================');

/* ---------------- P1: wiki image negative cache on a NETWORK failure ------ */
console.log('\nP1 loadWikiThumb: is a transient failure cached as "no photo"?');
{
  const o = { id: 'ngc5457', primary_name: 'M101', messier: 'M101', ngcic: 'NGC 5457', wiki: '' };
  const imgEl = makeEl('img'), phEl = makeEl('div');
  const key = 'w:' + o.id;

  for (const mode of ['reject', '429', '404', 'disambig-then-image']) {
    /* fresh image DB for each scenario */
    _dbs.delete('nightseam-images');
    fetchMode = mode;
    imgEl.src = '';
    q('#d-wikilink').href = '';
    await A.loadWikiThumb(o, imgEl, phEl);
    const rec = (storesOf('nightseam-images').get('thumbs') || new Map()).get(key);
    info(`fetch=${mode}: cached=${rec ? JSON.stringify(rec).slice(0, 40) : 'nothing'} | message="${phEl.textContent}"`);
    if (mode === '429') ok(!rec, 'HTTP 429 (rate limited) is NOT cached -> stays retryable');
    if (mode === '404') ok(!!rec && rec.missing === true, 'HTTP 404 (no page at all) IS cached as definitive');
    if (mode === 'reject') {
      ok(!rec, 'a rejected fetch (offline / DNS / abort) must NOT be cached as definitive  [expected FAIL = defect]');
      ok(phEl.textContent.includes('no photo on Wikipedia'),
        `offline shows the DEFINITIVE wording to the user: "${phEl.textContent}"`);
    }
    if (mode === 'disambig-then-image') {
      info(`titles tried: ${JSON.stringify(fetchCalls.filter((c) => c.includes('summary')).map((c) => decodeURIComponent(c.split('/').pop())))}`);
      ok(!!rec && !!rec.blob, 'the disambiguation page is skipped and the next designation resolves the photo');
      ok(q('#d-wikilink').href === 'https://en.wikipedia.org/wiki/Pinwheel_Galaxy',
        `the wiki link is rewritten to the canonical article (${q('#d-wikilink').href})`);
      ok(imgEl.src.startsWith('blob:'), `the resolved photo is shown (img src=${imgEl.src.slice(0, 24)}…)`);
    }
  }
}

/* ---------------- P2: restore staging order + failed clear --------------- */
console.log('\nP2 webstore.restoreBackup: is the WHOLE bundle validated before any write?');
{
  _dbs.delete('nightseam-db-v1');
  await WS.saveSiteRec({ id: 'keep', name: 'Keep', lat: 52, lon: 13, elev: 0, tz: null });
  const current = await WS.collectBackup(H.getPrefs(), H.exportPanos(), 'dome');
  const bundle = {
    app: 'nightseam-web', version: 2, sites: [{ id: 'evil', name: 'Evil', lat: 1, lon: 2, elev: 0, tz: null }],
    rigs: [], targets: [], panos: 'not-an-object', prefs: {}, theme: 'dome',
  };
  const staged = await WS.restoreBackup(bundle, current);          // does NOT throw
  const idsAfter = (await WS.getSites()).map((s) => s.id);
  info(`staged.panos=${JSON.stringify(staged.panos)} | normalizePanos(...)=${JSON.stringify(H.normalizePanos(staged.panos))} | sites now=${JSON.stringify(idsAfter)}`);
  ok(staged.panos === null, 'the unusable panorama section is carried into the "staged" result');
  ok(idsAfter.join(',') === 'evil', 'the user records were ALREADY REPLACED by the rejected bundle (app.js throws only after this)');
  ok(H.normalizePanos(staged.panos) === null, 'the caller-side panorama validation fails only after the write');

  /* does the internal rollback cover a failed PUT? (the documented path) */
  _dbs.delete('nightseam-db-v1');
  await WS.saveSiteRec({ id: 'keep', name: 'Keep', lat: 52, lon: 13, elev: 0, tz: null });
  CTL.failPut.sites = 1;
  let err = null;
  try { await WS.restoreBackup(bundle, await WS.collectBackup(H.getPrefs(), H.exportPanos(), 'dome')); } catch (e) { err = e; }
  CTL.failPut.sites = 0;
  const idsRollback = (await WS.getSites()).map((s) => s.id);
  ok(!!err && idsRollback.join(',') === 'keep', `a failed PUT throws and rolls the records back (${err && err.message}, sites=${idsRollback})`);

  /* a failed CLEAR is ignored by writeStaged */
  _dbs.delete('nightseam-db-v1');
  await WS.saveSiteRec({ id: 'keep', name: 'Keep', lat: 52, lon: 13, elev: 0, tz: null });
  CTL.failClear.sites = 1;
  const ok2 = await WS.restoreBackup(bundle, null).then(() => true, () => false);
  CTL.failClear.sites = 0;
  const idsMerged = (await WS.getSites()).map((s) => s.id).sort();
  info(`failed clear -> restore "succeeded"=${ok2}, sites=${JSON.stringify(idsMerged)}`);
  ok(ok2 && idsMerged.length === 2, 'a failed clear() is swallowed: the restore reports success and merges old+new records  [expected FAIL = defect]');
}

/* ---------------- P3: stale custom targets after an import --------------- */
console.log('\nP3 reinitUserData: are custom targets that the backup dropped removed?');
{
  _dbs.delete('nightseam-db-v1');
  A.__setCAT([]);
  await WS.saveSiteRec({ id: 's1', name: 'Site', lat: 52, lon: 13, elev: 0, tz: null });
  await WS.saveTargetRec({ id: 'u_old', primary_name: 'Old target', ra_hours: 1, dec_deg: 2, otype: 'galaxy', size_am: '5' });
  await A.reinitUserData();
  ok(A.__getCAT().some((o) => o.id === 'u_old'), 'before the import the custom target is in the catalog');
  /* what a restore does: the store now holds the BACKUP's targets only */
  await WS.deleteTargetRec('u_old');
  await WS.saveTargetRec({ id: 'u_new', primary_name: 'New target', ra_hours: 3, dec_deg: 4, otype: 'galaxy', size_am: '5' });
  await A.reinitUserData();
  const cat = A.__getCAT().map((o) => o.id);
  info(`catalog after the import: ${JSON.stringify(cat)} | store: ${JSON.stringify((await WS.getTargets()).map((t) => t.id))}`);
  ok(!cat.includes('u_old'), 'a custom target the backup dropped is gone from the catalog  [expected FAIL = defect]');
  ok(cat.includes('u_new'), 'the imported custom target is listed');
}

/* P4 (IndexedDB denied) lives in web_probe_idb_denied.mjs: the store module
   caches its connection, so it needs a fresh process. */

/* ---------------- P5: the editor dirty flag across a re-render ----------- */
console.log('\nP5 horizon editor: does a re-render reset the unsaved flag?');
{
  const p = H.newPano('dirty-probe');
  const persisted = () => {
    const raw = JSON.parse(localStorage.getItem('nightseam_panos_v1'));
    const rec = raw.panos.find((x) => x.id === p.id);
    return rec ? rec.strokes.length : -1;
  };
  const h0 = H.newHistory(p);                       // editor opened (clean)
  ok(!H.historyDirty(h0, p), 'a freshly opened editor is clean');
  p.strokes.push({ m: 'b', x: 10, y: 10, r: 5 });   // the user paints: in-memory only
  ok(H.historyDirty(h0, p), 'painting marks the editor dirty');
  ok(persisted() === 0, `the paint is NOT persisted yet (stored strokes=${persisted()})`);
  const h1 = H.newHistory(p);                       // == what renderHorizon() does after refreshView()
  ok(H.historyDirty(h1, p), 're-rendering the editor keeps the unsaved flag  [expected FAIL = defect]');
  ok(H.historyCanUndo(h1) === false && h1.entries.length === 1,
    `the re-render also discards the undo history (entries=${h1.entries.length}, canUndo=${H.historyCanUndo(h1)})`);
}

/* ---------------- P6: D2 rig unit adapter (control) --------------------- */
console.log('\nP6 webstore.getRigs: legacy degree rigs convert exactly once');
{
  _dbs.delete('nightseam-db-v1');
  await WS.saveRigRec({ id: 'legacy', name: 'Legacy', focal_mm: 250, sensor_w: 5.57, sensor_h: 3.13, fov_w: 1.276, fov_h: 0.717 });
  const r1 = (await WS.getRigs()).find((r) => r.id === 'legacy');
  const r2 = (await WS.getRigs()).find((r) => r.id === 'legacy');
  info(`first load fov_w=${r1.fov_w.toFixed(3)} arcmin, fov_unit=${r1.fov_unit}; second load fov_w=${r2.fov_w.toFixed(3)}`);
  ok(Math.abs(r1.fov_w - 76.56) < 0.01 && r1.fov_unit === 'arcmin', 'degrees -> arcmin on load');
  ok(Math.abs(r2.fov_w - r1.fov_w) < 1e-9, 'the conversion does not compound across loads (refuted candidate)');
}

console.log(`\n== probe summary: ${pass} passed, ${fail} failed ==`);
writeFileSync(new URL('./probe-result.json', import.meta.url),
  JSON.stringify({ pass, fail, at: new Date().toISOString() }, null, 1));
process.exitCode = 0;
